                Wrap(
                  spacing: 6,
                  children: movie.genres.map((genre) {
                    return Chip(label: Text(genre));
                  }).toList(),
                ),

                const SizedBox(height: 12),
                Text('     ${movie.overview}'),

                const SizedBox(height: 20),

                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceAround,
                  children: [
                    ListenableBuilder(
